CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.pricing_metrics
COMMENT 'Quote and conversion KPIs over the quote book - volumes, conversion and rated versus quoted premium by line and period. The pricing and demand view of the funnel. Amounts are in original quote currency; group by or filter on currency_code before summing money. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_policy.quote

joins:
  - name: line_of_business
    source: lr_serverless_aws_us_catalog.bricksurance_reference.line_of_business
    on: source.line_of_business_code = line_of_business.line_of_business_code

dimensions:
  - name: quote_month
    expr: DATE_TRUNC('MONTH', quote_date)
  - name: line_of_business
    expr: line_of_business.label
  - name: line_of_business_code
    expr: source.line_of_business_code
  - name: currency_code
    expr: currency_code

measures:
  - name: quote_count
    expr: COUNT(DISTINCT quote_id)
  - name: converted_count
    expr: COUNT(DISTINCT CASE WHEN conversion_flag THEN quote_id END)
  - name: conversion_rate
    expr: COUNT(DISTINCT CASE WHEN conversion_flag THEN quote_id END) / NULLIF(COUNT(DISTINCT quote_id), 0)
  - name: quoted_premium_total
    expr: SUM(quoted_gross_premium)
  - name: rated_premium_total
    expr: SUM(rated_gross_premium)
$$;
